  // The voice page. It is spoken at, and someone who talks to their agent in Russian should not be
  // answered by an English screen; these are the words around the conversation, not in it.
  "voice.beta": { en: "beta", ru: "бета" },
  "voice.transcript": { en: "Transcript", ru: "Расшифровка" },
  "voice.new": { en: "New conversation", ru: "Новый разговор" },
