  "folder.remove.body": { en: "Nothing in {path} is deleted; the agents of this project stop seeing it. An agent working in it has to be moved or removed first.", ru: "Ничего в {path} не удаляется; агенты проекта просто перестанут её видеть. Агента, который работает в ней, сначала нужно перенести или убрать." },
