  "folder.added.unmounted": { en: "{name} added — it is not mounted here yet", ru: "{name}: папка добавлена, но здесь ещё не подключена" },
  "folder.label": { en: "Label, if the folder name is not enough", ru: "Подпись, если имени папки мало" },
  "folder.label.placeholder": { en: "Docs, Backend…", ru: "Документация, бэкенд…" },
  "folder.mount.warning": {
    en: "In Docker the bot sees a folder only once it is mounted into the container at the same path. The desktop launcher adds the mount; Stop and then Start applies it. On a server, add the folder to the compose file's volumes and start the stack again.",
    ru: "В Docker бот видит папку, только когда она смонтирована в контейнер по тому же пути. Настольный лаунчер добавит монтирование, а применят его «Стоп» и «Старт». На сервере добавьте папку в volumes compose-файла и перезапустите стек.",
  },
  "folder.host.hint": {
    en: "A host folder is worked in through the host terminal daemon: Daedalus agents, CLI agents and your own shells all reach it. Type its full path on the host.",
    ru: "С папкой на хосте работают через демон терминала хоста: агенты Daedalus, CLI-агенты и ваши оболочки её видят. Введите её полный путь на хосте.",
  },
  "folder.host.hint.nobridge": {
    en: "A host folder needs the host terminal daemon, which is not answering: nothing can work in it until it is installed and running. Type its full path on the host.",
    ru: "Для папки на хосте нужен демон терминала хоста, а он не отвечает: пока он не установлен и не запущен, с папкой ничто не работает. Введите её полный путь на хосте.",
  },
  "folder.reach.ok": { en: "Every agent of this project reads and writes it.", ru: "Все агенты проекта читают и пишут её." },
  "folder.reach.readonly": { en: "Agents read it and never write it.", ru: "Агенты читают её и никогда не пишут." },
  "folder.reach.notwritable": { en: "The bot may not write here, so agents can only read it.", ru: "Бот не может писать сюда, поэтому агенты только читают её." },
  "folder.reach.unmounted": { en: "Not mounted in the container yet: the launcher adds it, and Stop then Start applies it.", ru: "Ещё не смонтирована в контейнер: лаунчер добавит её, а применят «Стоп» и «Старт»." },
  "folder.reach.missing": { en: "Not found on this machine. Put the folder back, or forget it here.", ru: "Не найдена на этой машине. Верните папку или уберите её здесь." },
  "folder.reach.terminals": { en: "On the host: every agent reaches it through the host terminal daemon.", ru: "На хосте: все агенты работают с ней через демон терминала хоста." },
  "folder.reach.none": { en: "On the host, and the host terminal bridge is not installed: nothing can work in it yet.", ru: "На хосте, а мост к терминалу хоста не установлен: пока с ней ничто не может работать." },
