  "pboard.unknown.help": { en: "These workers were told to stop but didn't confirm it in time. Their tasks stay locked until the stop is confirmed; nothing is restarted.", ru: "Этим исполнителям велели остановиться, но они не подтвердили это вовремя. Их задачи заняты, пока остановка не подтверждена; ничего не перезапускается." },
