  "pboard.unknown.blocker.previous_host": { en: "This worker ran before the server restarted, so its stop can't be confirmed from here. Make sure it is no longer running on the machine.", ru: "Исполнитель работал до перезапуска сервера, поэтому отсюда остановку не подтвердить. Убедитесь, что он больше не работает на машине." },
