  "pboard.unknown.blocker.exit_unobserved": { en: "The worker may still be running. Check its run or terminal, then refresh.", ru: "Исполнитель, возможно, ещё работает. Проверьте его запуск или терминал, затем обновите." },
  "pboard.unknown.blocker.containment_unavailable": { en: "This command-line worker wasn't isolated, so its child processes may still be running. Check the machine yourself; the task stays locked.", ru: "Этот исполнитель командной строки не был изолирован — его дочерние процессы могут ещё работать. Проверьте машину сами; задача остаётся занятой." },
  "pboard.unknown.blocker.container_not_empty": { en: "The worker exited, but some of its processes may still be running. Refresh once they stop.", ru: "Исполнитель завершился, но часть его процессов может ещё работать. Обновите, когда они остановятся." },
