  "budget.coordinatorQuote": { en: "One {model} coordinator call can hold up to {amount} at current rates; this is a worst-case reserve, not predicted spend.", ru: "Один вызов координатора {model} может зарезервировать до {amount} по текущим тарифам; это предел резерва, а не прогноз расхода." },
  "budget.belowQuote": { en: "The entered cap is below one coordinator call's reserve. Raise both caps to allow a call, or choose a model with a lower verified ceiling.", ru: "Введённый предел ниже резерва для одного вызова координатора. Увеличьте оба предела или выберите модель с меньшим подтверждённым потолком." },
