  "coordinatorHandoff.intro": { en: "The new coordinator's model is checked before the project is handed over. If that fails, the current coordinator stays.", ru: "Перед передачей проекта проверяется модель нового координатора. Если проверка не пройдёт, текущий координатор останется." },
