  "coordinatorHandoff.readFailed": { en: "Replacement status could not be read.", ru: "Не удалось прочитать состояние замены." },
  "coordinatorHandoff.pending": { en: "Couldn't confirm the replacement was requested. Try again.", ru: "Не удалось подтвердить запрос на замену. Повторите." },
  "coordinatorHandoff.collision": { en: "This replacement clashes with an earlier request. Check the current coordinator, then start a new replacement.", ru: "Эта замена расходится с предыдущим запросом. Проверьте текущего координатора и начните замену заново." },
  "coordinatorHandoff.retry": { en: "Try again", ru: "Повторить" },
  "coordinatorHandoff.conflict": { en: "The coordinator or project changed. Review the current state before trying again.", ru: "Координатор или проект изменился. Проверьте текущее состояние перед новой попыткой." },
  "coordinatorHandoff.review": { en: "Review current state", ru: "Проверить состояние" },
  "coordinatorHandoff.noOffice": { en: "There is no active coordinator to replace.", ru: "Нет действующего координатора для замены." },
  "coordinatorHandoff.reason": { en: "Reason or context (optional)", ru: "Причина или контекст (необязательно)" },
  "coordinatorHandoff.action": { en: "Check and replace", ru: "Проверить и заменить" },
  "coordinatorHandoff.confirm.title": { en: "Replace this coordinator?", ru: "Заменить этого координатора?" },
  "coordinatorHandoff.confirm.body": { en: "The server checks that the model is available, prepares a new session, then hands the project over. Project schedules will pause for your approval under the new coordinator.", ru: "Сервер проверит каталог настроенной модели, подготовит новую сессию и затем передаст ей проект. Расписания проекта будут ждать вашего разрешения для нового координатора." },
  "coordinatorHandoff.schedules": { en: "{count} project schedules need your approval before they can run under the new coordinator. Earlier approvals did not transfer.", ru: "Расписаний, которым нужно ваше разрешение перед запуском у нового координатора: {count}. Прежние разрешения не перенесены." },
  "coordinatorHandoff.readinessLimit": { en: "The model catalogue check confirms access and the advertised model. It does not prove an inference will succeed or that quota is available.", ru: "Проверка каталога подтверждает доступ и наличие модели. Она не доказывает успешный запрос к модели или наличие квоты." },
  "coordinatorHandoff.committed": { en: "Coordinator replaced. The old session is shutting down.", ru: "Координатор заменён. Прежняя сессия завершается." },
  "coordinatorHandoff.receipt": { en: "Details", ru: "Подробнее" },
  "coordinatorHandoff.state.preparing": { en: "Preparing the replacement", ru: "Подготовка замены" },
  "coordinatorHandoff.state.blocked": { en: "Replacement blocked; the current coordinator stays", ru: "Замена заблокирована; текущий координатор остаётся" },
  "coordinatorHandoff.state.retirement_pending": { en: "New coordinator is working; the old one hasn't confirmed it stopped", ru: "Новый координатор работает; прежний ещё не подтвердил остановку" },
  "coordinatorHandoff.state.completed": { en: "Coordinator replaced; the old session was asked to stop", ru: "Координатор заменён; прежней сессии велено остановиться" },
  "coordinatorHandoff.blocker.authentication_failed": { en: "Model catalogue authentication failed. Check the provider key, then try a new request.", ru: "Ошибка доступа к каталогу моделей. Проверьте ключ провайдера и отправьте новый запрос." },
  "coordinatorHandoff.blocker.model_unavailable": { en: "The selected model is not configured. Check Models in Settings.", ru: "Выбранная модель не настроена. Проверьте раздел «Модели» в настройках." },
  "coordinatorHandoff.blocker.model_not_advertised": { en: "The provider did not list this exact model. Check the model ID.", ru: "Провайдер не указал эту модель в каталоге. Проверьте идентификатор модели." },
  "coordinatorHandoff.blocker.catalogue_unavailable": { en: "The provider's model catalogue is unavailable. Check the connection and try again.", ru: "Каталог моделей провайдера недоступен. Проверьте соединение и повторите попытку." },
  "coordinatorHandoff.blocker.configuration_changed": { en: "Provider settings changed during preparation. Review them and try again.", ru: "Настройки провайдера изменились во время подготовки. Проверьте их и повторите попытку." },
  "coordinatorHandoff.blocker.preparation_interrupted": { en: "Preparation was interrupted before the handover. The current coordinator stays.", ru: "Подготовка прервалась до передачи. Текущий координатор остаётся." },
  "coordinatorHandoff.blocker.schedule_delivery_unconfirmed": { en: "A project schedule's last run wasn't confirmed. Check it in Schedules before replacing the coordinator.", ru: "Последний запуск расписания проекта не подтверждён. Проверьте его в расписаниях перед заменой координатора." },
  "coordinatorHandoff.blocker.schedule_scope_changed": { en: "A project schedule or its approval no longer matches this coordinator. Review it before trying a new replacement.", ru: "Расписание проекта или его разрешение больше не соответствует координатору. Проверьте его перед новой заменой." },
  "coordinatorHandoff.blocker.retirement_unconfirmed": { en: "The new coordinator is working, but the old one hasn't confirmed it stopped.", ru: "Новый координатор работает, но прежний ещё не подтвердил остановку." },
  "coordinatorHandoff.blocker.unknown": { en: "The host could not confirm readiness. Review the provider and retry.", ru: "Сервер не подтвердил готовность. Проверьте провайдера и повторите попытку." },
  "coordinatorHandoff.blocker.preparation_failed": { en: "Preparation failed. The old coordinator remains active.", ru: "Подготовка не удалась. Прежний координатор остаётся действующим." },
  "coordinatorHandoff.blocker.mutation_in_flight": { en: "A coordinator action is still running. Wait for it to finish, then try a new replacement request.", ru: "Действие координатора ещё выполняется. Дождитесь завершения и отправьте новый запрос на замену." },
