  "authority.bundle.unknown": { en: "Other approval", ru: "Другое разрешение" },
  "authority.definitionChanged": { en: "The permission set changed on the server. Look at what it now allows; approving is unavailable here.", ru: "Набор прав на сервере изменился. Посмотрите, что он теперь разрешает; одобрение здесь недоступно." },
  "authority.bundle.help.planning": { en: "May create and update project tasks, add or withdraw requirements, and apply a pending requirement after the previous execution exits. Stopping and launching work need separate approval.", ru: "Можно создавать и менять задачи проекта, добавлять или отзывать требования и применять отложенное требование после завершения предыдущего запуска. Остановка и запуск работы требуют отдельных разрешений." },
  "authority.bundle.help.assignment": { en: "May choose a project worker for the selected unowned, unstarted task. Its title, brief, criteria, files and existing owner cannot be changed. Launching needs separate approval.", ru: "Можно выбрать сотрудника проекта для выбранной свободной задачи, которая ещё не запускалась. Название, описание, критерии, файлы и существующего исполнителя менять нельзя. Запуск требует отдельного разрешения." },
  "authority.bundle.help.assignment_execution": { en: "May choose a project worker for this unowned task, launch or stop its execution, and release that worker. The task's title, brief, criteria and files cannot be changed. Review and final acceptance remain separate.", ru: "Можно выбрать сотрудника для этой свободной задачи, запускать или останавливать её выполнение и освобождать сотрудника. Название, описание, критерии и файлы менять нельзя. Проверка и окончательное принятие требуют отдельных решений." },
  "authority.bundle.help.execution": { en: "May launch the selected task and release its staff member or stop its bound execution. Planning and review need separate approval.", ru: "Можно запускать выбранную задачу, освобождать её сотрудника или останавливать привязанный запуск. Планирование и проверка требуют отдельных разрешений." },
  "authority.bundle.help.execution_project": { en: "May launch project tasks, release their staff members and stop their bound executions. This project-wide scope needs explicit approval.", ru: "Можно запускать задачи проекта, освобождать их сотрудников и останавливать привязанные запуски. Такое разрешение на весь проект требует явного подтверждения." },
  "authority.bundle.help.review": { en: "May record review verdicts and return results. Operator acceptance remains separate.", ru: "Можно выносить вердикты проверки и возвращать результаты. Окончательное принятие оператором остаётся отдельным." },
  "authority.bundle.help.watch": { en: "May create, change and remove project watches. While this approval lasts, matching events may wake the coordinator, send staff messages, or notify you without a new approval each time.", ru: "Можно создавать, менять и удалять наблюдения проекта. Пока действует разрешение, подходящие события могут будить координатора, отправлять сообщения сотрудникам или уведомлять вас без нового разрешения каждый раз." },
  "authority.bundle.help.wake_internal": { en: "The current coordinator may schedule or cancel its own one-time wake-up within this approval's 24-hour limit. It ends when this approval is withdrawn or the coordinator changes; it cannot send external messages or start recurring runs.", ru: "Текущий координатор может назначить или отменить своё разовое пробуждение в пределах 24 часов действия разрешения. При отзыве именно этого разрешения или смене координатора оно прекращается; внешние сообщения и повторяющиеся запуски недоступны." },
