  "push.state.on": { en: "Notifications reach this device even when the app is closed.", ru: "Уведомления приходят на это устройство, даже когда приложение закрыто." },
  "push.state.off": { en: "While the app is closed, this device hears nothing. Turn push on to get questions, permission requests and results here.", ru: "Пока приложение закрыто, это устройство ничего не узнаёт. Включите push, чтобы вопросы, запросы разрешений и результаты приходили сюда." },
  "push.state.denied": { en: "Notifications are blocked for this site in the browser settings. Allow them there, then come back here.", ru: "Уведомления для этого сайта запрещены в настройках браузера. Разрешите их там и вернитесь сюда." },
  "push.state.unsupported": { en: "This browser cannot receive push here. Open the app at its public https address in Chrome, Edge, Firefox or Safari; the desktop launcher shows notifications by itself.", ru: "Этот браузер не может получать push здесь. Откройте приложение по публичному https-адресу в Chrome, Edge, Firefox или Safari; десктопный лаунчер показывает уведомления сам." },
  "push.state.unavailable": { en: "Push needs a public https address for the app, set on the host.", ru: "Для push у приложения должен быть публичный https-адрес, заданный на хосте." },
  "push.state.telegram": { en: "Inside Telegram the bot is your push: questions, requests and results arrive as its messages.", ru: "Внутри Telegram push — это сам бот: вопросы, запросы и результаты приходят его сообщениями." },
  "push.state.needs-home-screen": { en: "On iPhone and iPad, notifications work only for the app added to the Home Screen. There they arrive without buttons: a tap opens the request.", ru: "На iPhone и iPad уведомления работают только у приложения на экране «Домой». Там они приходят без кнопок: нажатие открывает запрос." },
  "push.ios.share": { en: "Tap Share in Safari.", ru: "Нажмите «Поделиться» в Safari." },
  "push.ios.add": { en: "Choose “Add to Home Screen”.", ru: "Выберите «На экран „Домой“»." },
  "push.ios.open": { en: "Open Daedalus from the Home Screen and turn push on here.", ru: "Откройте Daedalus с экрана «Домой» и включите push здесь." },
