  "push.test": { en: "Test notification", ru: "Проверка уведомлений" },
  "push.test.sub": { en: "Sends one notification through every channel there is and shows where it went.", ru: "Отправляет одно уведомление по всем каналам и показывает, куда оно дошло." },
