  "nset.quick.sub": { en: "Allow, deny and answer from a notification without opening the app, where the request allows it. Permissions on the host machine are always answered in the app.", ru: "Разрешать, отклонять и отвечать прямо из уведомления, не открывая приложение, если запрос это допускает. Разрешения на хост-машине всегда даются в приложении." },
  "nset.cover": { en: "Don't push what Telegram delivered", ru: "Не дублировать push то, что пришло в Telegram" },
  "nset.cover.sub": { en: "One phone, one buzz: what the bot already sent is not pushed or shown on the desktop as well.", ru: "Один телефон — один сигнал: то, что уже прислал бот, не приходит ещё и push или на рабочий стол." },
  "nset.mute.title": { en: "Muted projects", ru: "Приглушённые проекты" },
  "nset.mute.sub": { en: "A muted project's notifications stay in the list with no toast, push, desktop or Telegram. Urgent ones still come through.", ru: "Уведомления приглушённого проекта остаются в списке без всплывающих окон, push, рабочего стола и Telegram. Срочные всё равно приходят." },
  "nset.mute.none": { en: "No projects yet.", ru: "Проектов пока нет." },
  "nset.mute.off": { en: "Notifications on", ru: "Уведомления включены" },
  "nset.mute.until": { en: "Muted until {time}", ru: "Приглушён до {time}" },
  "nset.mute.forever": { en: "Muted until you lift it", ru: "Приглушён, пока вы не снимете" },
  "nset.mute.group": { en: "Mute {name}", ru: "Приглушить {name}" },
  "nset.mute.hour": { en: "1 h", ru: "1 ч" },
  "nset.mute.tomorrow": { en: "Until tomorrow", ru: "До завтра" },
  "nset.mute.always": { en: "Always", ru: "Всегда" },
  "nset.mute.unmute": { en: "Unmute", ru: "Снять" },
  "nset.popups.title": { en: "Inside the app", ru: "Внутри приложения" },
  "nset.popups": { en: "Show pop-ups in the app", ru: "Показывать всплывающие уведомления в приложении" },
  "nset.popups.sub": { en: "New notifications pop up in a corner of the app for a few seconds. Off: they go only to the bell and the inbox. Push, desktop and Telegram notifications are not affected, and each device keeps its own choice.", ru: "Новые уведомления на несколько секунд всплывают в углу приложения. Если выключить, они попадают только под колокольчик и во входящие. Push, уведомления рабочего стола и Telegram это не затрагивает; у каждого устройства свой выбор." },
  "nset.devices.title": { en: "Devices with push", ru: "Устройства с push" },
  "nset.devices.sub": { en: "Every browser and phone that receives push. A device that keeps failing for a week is removed by itself.", ru: "Все браузеры и телефоны, получающие push. Устройство, которое не отвечает неделю, удаляется само." },
  "nset.devices.unnamed": { en: "A browser", ru: "Браузер" },
  "nset.devices.lastok": { en: "last delivered {t}", ru: "последняя доставка {t}" },
  "nset.devices.never": { en: "nothing delivered yet", ru: "ещё ничего не доставлено" },
  "nset.devices.failures": { en: "{n} failure|{n} failures", ru: "{n} сбой|{n} сбоя|{n} сбоев" },
  "nset.devices.thishint": { en: "Turn push off above to remove it", ru: "Чтобы убрать, выключите push выше" },
  "nset.devices.removed": { en: "Device removed", ru: "Устройство убрано" },
  "nset.test.line": { en: "{channel}: {outcome}", ru: "{channel}: {outcome}" },
  "nset.out.toast": { en: "shown here", ru: "показано здесь" },
  "nset.out.sent": { en: "sent", ru: "отправлено" },
  "nset.out.nodevice": { en: "no device has push turned on", ru: "ни на одном устройстве push не включён" },
  "nset.out.nolauncher": { en: "no desktop launcher is listening", ru: "десктопный лаунчер не подключён" },
  "nset.out.nobot": { en: "no Telegram bot is connected", ru: "бот Telegram не подключён" },
  "nset.out.notopic": { en: "there is no chat to send to", ru: "некуда отправить" },
  "nset.out.failed": { en: "failed: {why}", ru: "не удалось: {why}" },
  "nset.out.device": { en: "{device}, {outcome}", ru: "{device}, {outcome}" },
  "browser.replay": { en: "Recording", ru: "Запись" },
  "browser.replay.at": { en: "{time} · {n} of {of}", ru: "{time} · {n} из {of}" },
  "browser.replay.scrub": { en: "Keyframe", ru: "Ключевой кадр" },
