  // Settings -> Components. The optional pieces of an installation, each with what it unlocks and
  // what it would take to get it. A portable build leaves most of them out on purpose; what was
  // missing was anywhere that said so, which is why every word of this section exists.
  "comp.title": { en: "Components", ru: "Компоненты" },
  "comp.intro": {
    en: "The parts an installation does not have to carry. Each one is left out because most sessions never need it, and each one can be added here — what it unlocks is written on its card, and nothing is downloaded until you ask.",
    ru: "Части, которые установка может и не нести. Каждая вынесена наружу потому, что большинству сессий она не нужна, и каждую можно добавить прямо здесь: что она открывает, написано на её карточке, и ничего не скачивается, пока вы не попросите.",
  },
  "comp.mode.native": { en: "This installation runs as processes on this machine.", ru: "Эта установка работает процессами на этой машине." },
  "comp.mode.docker": { en: "This installation runs in a container, so what it has was decided by the image it runs.", ru: "Эта установка работает в контейнере, и её состав определён образом, из которого она запущена." },
  "comp.disk": { en: "{size} on disk in models and voices", ru: "{size} на диске — модели и голоса" },
  "comp.loading": { en: "Reading what this installation has…", ru: "Читаем, что есть в этой установке…" },
  "comp.state.installed": { en: "installed", ru: "установлено" },
  "comp.state.missing": { en: "not installed", ru: "не установлено" },
  "comp.state.installing": { en: "installing", ru: "устанавливается" },
  "comp.state.unavailable": { en: "unavailable here", ru: "здесь недоступно" },

  "comp.name.speech": { en: "Speech runtime", ru: "Речевой движок" },
  "comp.what.speech": { en: "Runs the recognition models and the voices on this machine's processor. Without it the browser does the listening and the speaking.", ru: "Запускает модели распознавания и голоса на процессоре этой машины. Без него слушает и говорит сам браузер." },
  "comp.name.stt-models": { en: "Recognition models", ru: "Модели распознавания" },
  "comp.what.stt-models": { en: "The models that turn speech into words. Chosen one at a time in Settings → Voice & speech.", ru: "Модели, превращающие речь в слова. Выбираются по одной в «Настройки → Голос и речь»." },
  "comp.name.tts-voices": { en: "Voices", ru: "Голоса" },
  "comp.what.tts-voices": { en: "The voices that read the answers aloud. Chosen one at a time in Settings → Voice & speech.", ru: "Голоса, которыми читаются ответы. Выбираются по одному в «Настройки → Голос и речь»." },
  "comp.name.browser": { en: "Headless browser", ru: "Браузер без окна" },
  "comp.what.browser": { en: "Opens pages, drives them and takes pictures of them. Several skills need it and say so when it is not there.", ru: "Открывает страницы, управляет ими и снимает их. Нескольким навыкам он нужен, и без него они об этом говорят." },
  "comp.name.node": { en: "Node", ru: "Node" },
  "comp.what.node": { en: "The runtime that skills need when they shell out to npx. Nothing else in the agent uses it.", ru: "Среда, нужная навыкам, которые вызывают npx. Больше агенту она ни для чего не нужна." },
  "comp.name.git": { en: "Git", ru: "Git" },
  "comp.what.git": { en: "Reads and writes the checkouts: the agent's own code, and every project you add.", ru: "Читает и пишет репозитории: и собственный код агента, и каждый добавленный проект." },
  "comp.name.ripgrep": { en: "ripgrep", ru: "ripgrep" },
  "comp.what.ripgrep": { en: "The search that reads a large tree quickly. Without it, searching is slower and narrower.", ru: "Поиск, быстро читающий большое дерево файлов. Без него поиск медленнее и уже." },
  "comp.name.opus": { en: "Opus decoder", ru: "Декодер Opus" },
  "comp.what.opus": { en: "Turns a Telegram voice note into samples a model can read. A megabyte and a half; without it, only plain recordings can be transcribed.", ru: "Превращает голосовое сообщение Telegram в отсчёты, понятные модели. Полтора мегабайта; без него расшифровать можно только простые записи." },
  "comp.name.bwrap": { en: "Sandbox (bubblewrap)", ru: "Песочница (bubblewrap)" },
  "comp.what.bwrap": { en: "Keeps a command the agent runs inside the folder it was given. Without it, Exec either runs unconfined or is refused, depending on the setting.", ru: "Удерживает команду агента внутри выданной ей папки. Без неё Exec либо работает без ограничений, либо запрещён — смотря как настроено." },

  "comp.unlocks": { en: "Unlocks", ru: "Открывает" },
  "comp.enables.stt": { en: "recognition on this machine", ru: "распознавание на этой машине" },
  "comp.enables.tts": { en: "a voice on this machine", ru: "голос на этой машине" },
  "comp.enables.voicenotes": { en: "voice notes in chat", ru: "голосовые сообщения в чате" },
  "comp.enables.skills.browser": { en: "the browser skills", ru: "навыки, работающие с браузером" },
  "comp.enables.screenshots": { en: "pictures of a page", ru: "снимки страниц" },
  "comp.enables.skills.node": { en: "the skills that run npx", ru: "навыки, вызывающие npx" },
  "comp.enables.npx": { en: "npx in a command", ru: "npx в командах" },
  "comp.enables.selfdev": { en: "changing its own code", ru: "изменение собственного кода" },
  "comp.enables.projects": { en: "projects", ru: "проекты" },
  "comp.enables.search": { en: "fast search", ru: "быстрый поиск" },
  "comp.enables.sandbox": { en: "the command sandbox", ru: "песочницу для команд" },

