    en: "What turns a voice note into words: an OpenAI-compatible /audio/transcriptions endpoint, or a speech model installed below that runs on this machine. A long recording is sent in pieces the endpoint accepts, and one that could not be transcribed is kept to retry or attach. The agent receives the words marked as a transcript, never the audio.",
    ru: "Чем голосовая заметка превращается в текст: совместимым с OpenAI адресом /audio/transcriptions или речевой моделью, установленной ниже и работающей на этой машине. Длинная запись отправляется частями, которые адрес принимает, а нерасшифрованная сохраняется, чтобы повторить или приложить её. Агент получает расшифровку, помеченную как расшифровка, но не саму запись.",
