  "settings.chat.verbosity": { en: "Telegram verbosity", ru: "Подробность в Telegram" },
  "settings.chat.verbosity.sub": { en: "0: the tool calls and the answer. 1: also the model's notes between the calls. 2: also the start of each tool's result.", ru: "0: вызовы инструментов и ответ. 1: ещё заметки модели между вызовами. 2: ещё начало результата каждого инструмента." },
